const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  let maxDistanz = 50;
  let foundField = null;
  let foundValue = null;
  const distanzFields = [];

  // Suche ALLE Felder die 'distanz' enthalten
  for (const key of Object.keys(data)) {
    if (key.toLowerCase().includes('distanz')) {
      distanzFields.push({
        feld: key,
        wert: data[key],
        typ: typeof data[key]
      });

      if (!foundField) {
        foundField = key;
        foundValue = data[key];
        const match = String(data[key]).match(/\d+/);
        if (match) maxDistanz = parseInt(match[0]);
      }
    }
  }

  results.push({
    json: {
      name: data.property_name || 'Unbekannt',
      gefundene_distanz: maxDistanz,
      gefundenes_feld: foundField || 'KEIN FELD GEFUNDEN',
      gefundener_wert: foundValue,
      alle_distanz_felder: distanzFields
    }
  });
}

return results;
